PRICES = {"jacket": 1337_00, "socks": 5_00}     # cents, from our database

# Vulnerable: trusts price and quantity exactly as the client sent them
def total_v1(lines):
    return sum(l["price"] * l["qty"] for l in lines)

# Fixed: client sends product ids and quantities only; server validates both
def total_v2(lines, stock={"jacket": 3, "socks": 500}):
    total = 0
    for l in lines:
        sku, qty = l["sku"], l["qty"]
        if sku not in PRICES:
            raise ValueError(f"unknown product {sku!r}")
        if type(qty) is not int or not 1 <= qty <= stock[sku]:
            raise ValueError(f"bad quantity {qty!r} for {sku}")
        total += PRICES[sku] * qty
    return total

