# "10% off orders of 1000 or more" (amounts in whole units for clarity)
def subtotal(cart):
    return sum(price * qty for price, qty in cart.values())

# Vulnerable: the discount is decided once, when the code is entered,
# and stored as a fixed amount on the cart
def apply_code_v1(cart, state):
    if subtotal(cart) >= 1000:
        state["discount"] = subtotal(cart) // 10

def checkout_v1(cart, state):
    return subtotal(cart) - state.get("discount", 0)

# Fixed: store only the code; re-check the rule at checkout, every time
def checkout_v2(cart, state):
    s = subtotal(cart)
    if state.get("code") == "TENPCT" and s >= 1000:
        s -= s // 10
    return s

