# One order, three endpoints: add item, pay, confirm (ship).
# v1 trusts the UI to call them in order. v2 checks a transition table.
NEXT = {("cart", "pay"): "paid", ("paid", "confirm"): "confirmed"}

def v1(order, action, item=None):
    if action == "add":
        order["items"].append(item)
    elif action == "pay":
        order["paid_for"] = list(order["items"])
        order["state"] = "paid"
    elif action == "confirm":
        order["state"] = "confirmed"
        return "ship " + "+".join(order["items"])
    return "ok"

def v2(order, action, item=None):
    if action == "add":
        if order["state"] != "cart":
            return "409 cart locked"
        order["items"].append(item)
        return "ok"
    nxt = NEXT.get((order["state"], action))
    if nxt is None:
        return f"409 no {action} from {order['state']}"
    if action == "pay":
        order["paid_for"] = list(order["items"])
    order["state"] = nxt
    if action == "confirm":
        return "ship " + "+".join(order["paid_for"])
    return "ok"

script = [("add", "socks"), ("pay", None), ("add", "jacket"), ("confirm", None)]
for handler in (v1, v2):
    order = {"state": "cart", "items": [], "paid_for": []}
    print(handler.__name__, [handler(order, a, i) for a, i in script])
