print("v2 skip pay:", v2(skip, "confirm"))

// A fake async database: every call takes 5 ms, like a network round trip.
const wait = (ms) => new Promise((r) => setTimeout(r, ms))
const db = { used: new Set(), cartTotal: 100 }
const query = async (fn) => { await wait(5); return fn() }

// Vulnerable: check, then (after an await) act
async function applyCoupon(userId, code) {
  const alreadyUsed = await query(() => db.used.has(`${userId}:${code}`))
  if (alreadyUsed) return 'already used'
  await query(() => { db.cartTotal -= 10 })        // 10 off
  await query(() => db.used.add(`${userId}:${code}`))
  return 'applied'
}

