from collections import defaultdict

# (time in ms, user, endpoint, status) from the app's value-event log
log = [
    (1000, "u7", "POST /coupon", 200), (1001, "u7", "POST /coupon", 200),
    (1001, "u7", "POST /coupon", 200), (1002, "u7", "POST /coupon", 409),
    (5200, "u9", "POST /coupon", 200), (9100, "u9", "POST /coupon", 409),
    (7000, "u3", "POST /transfer", 200), (7400, "u3", "POST /transfer", 200),
]

def bursts(events, window_ms=10, min_hits=3):
    by_key = defaultdict(list)
    for t, user, ep, status in events:
        by_key[(user, ep)].append((t, status))
    for key, hits in by_key.items():
        hits.sort()
        for i in range(len(hits)):
            near = [h for h in hits[i:] if h[0] - hits[i][0] <= window_ms]
            if len(near) >= min_hits:
                ok = sum(1 for _, s in near if s == 200)
                yield key, len(near), ok
                break

for (user, ep), n, ok in bursts(log):
    print(f"ALERT {user} {ep}: {n} requests within 10 ms, {ok} succeeded")

